 "reportIntro": [
  {
   "k": "WHY",
   "title": "Why prepare a financial report?",
   "text": "To establish a clear and traceable picture of the project's current financial position. It shows the expenditure recorded for the reporting period and provides the controlled financial basis for review and validation."
  },
  {
   "k": "WHEN",
   "title": "When should it be prepared?",
   "text": "Prepare or update the financial report when a reporting package is required for the project. If future expenditure also needs to be planned or the budget needs to be revised, complete the current financial report first and then continue to Forecast & Budget Revision."
  },
  {
   "k": "HOW",
   "title": "How is it prepared?",
   "text": "Build the report from the correct project and financial data, reconcile the figures, apply the appropriate JP or VC reporting structure, complete the required controls and retain the validated reporting package."
  }
 ],
 "reportProcess": [
  {
   "title": "Prepare the financial report",
   "lead": "Establish the current financial position before any reconciliation or forward-looking exercise.",
   "action": "Use the correct project, Budget Head, reporting period and source figures to build the current report.",
   "control": "Confirm the reporting period, project references and opening structure before working on the figures.",
   "output": "A current financial report that can be reconciled and, if needed later, used as the baseline for Forecast & Budget Revision."
  },
  {
   "title": "Reconcile the financial position",
   "lead": "Make sure the report agrees with the available financial source data.",
   "action": "Compare spent, committed and available balances and investigate differences rather than carrying them forward.",
   "control": "Check totals, commitments and unexplained differences; keep the reconciliation trace visible.",
   "output": "A reconciled financial position with differences resolved or clearly explained."
  },
  {
   "title": "Apply the reporting structure",
   "lead": "Present the reconciled figures in the correct JP or VC reporting format.",
   "action": "Apply the correct layout, project references, Budget Head structure, formulas and presentation rules.",
   "control": "Preserve formulas and subtotals and make sure the reporting structure matches the applicable funding instrument.",
   "output": "A consistently structured JP / VC reporting package ready for control."
  },
  {
   "title": "Complete the reporting controls",
   "lead": "Check the financial package before it is treated as a controlled version.",
   "action": "Review financial consistency, supporting evidence, formulas, documentary references and the audit trail.",
   "control": "No unexplained discrepancy, broken formula or unsupported figure should remain before finalisation.",
   "output": "A controlled reporting package with a clear validation trail."
  },
  {
   "title": "Finalise and retain the report",
   "lead": "Close the reporting cycle and keep the version that supports subsequent review or planning.",
   "action": "Retain the final controlled report together with the relevant validation and supporting evidence.",
   "control": "Make sure the retained version is identifiable, complete and traceable to its supporting records.",
   "output": "The controlled financial report. If future expenditure or a budget revision is needed, continue from this baseline into Forecast & Budget Revision."
  }
 ],
